function tagChoices(tag,seen=[]){if(seen.includes(tag))return [];return (C.tags?.[tag]||[]).flatMap(v=>typeof v==='string'?v.startsWith('#')?tagChoices(v.slice(1),[...seen,tag]):[v]:v.id?[v.id]:[]);}
