function dropPercent(value,kind){
 if(value===undefined||value===null||value==='')return null;
 const text=String(value).trim(),number=Number(text.replace(/%$/,''));
 if(!Number.isFinite(number))return text;
 // Pokémon drops store fractions; held items and raid rewards store percent.
 const percent=kind==='pokemonDrop'&&!text.endsWith('%')?number*100:number;
 return percent.toFixed(2)+'%';
}
function dropQuantity(record){
 if(record.min!==undefined||record.max!==undefined){const min=record.min??record.max,max=record.max??record.min;return String(min)===String(max)?String(min):min+'–'+max;}
 const amount=record.item?.quantity??record.item?.Count??record.quantity??record.count;
 return amount===undefined?null:String(amount);
}
function acquisitionCard(kind,value){
 const record=typeof value==='string'?{Name:value}:value;
 const identifier=String(record.Name||record.name||record.pokemon||'');
 const isPokemon=['pokemonDrop','pokemonheldDrop','pokemonHeldList'].includes(kind);
 let label={structureDrop:'结构名',bossDrop:'Boss',pokechestDrop:'宝箱',pokestopDrop:'补给站',pickupDrop:'捡拾掉落池',pokemonDrop:'宝可梦名',pokemonheldDrop:'宝可梦名',pokemonHeldList:'宝可梦名',raidDrop:'巢穴星级',fishwaterDrop:'钓竿',fishlavaDrop:'钓竿'}[kind]||'获取方式';
 let name=isPokemon?pokemonLink(identifier):esc(acquisitionNames[identifier]||identifier||dropLabels[kind]);
 let icon='';
 if(isPokemon){const p=byNorm.pokemon.get(norm(identifier.split(/\s+form[=:]/i)[0]));if(p)icon=img(p.image,'drop-pokemon-image',p.name);}
 if(kind==='raidDrop')name=esc(record.star??'未记录')+' 星巢穴团体战';
 const locations=(record.stringLocationTypes||[]).map(s=>locationNames[s]||({'Old Rod Lava':'破旧钓竿（岩浆）','Good Rod Lava':'好钓竿（岩浆）','Super Rod Lava':'厉害钓竿（岩浆）',Forage:'觅食',Headbutt:'头锤', 'Rock Smash':'碎岩'}[s])||s);
 if(!identifier&&locations.length)name=esc(locations.join(' / '));
 const percent=dropPercent(record.percent??record.chance,kind),quantity=dropQuantity(record);
 let facts='';
 if(percent!==null)facts+=`<div><dt>出现几率</dt><dd>${esc(percent)}</dd></div>`;
 if(record.rarity!==undefined)facts+=`<div><dt>相对权重</dt><dd>${esc(record.rarity)}</dd></div>`;
 if(quantity!==null)facts+=`<div><dt>数量</dt><dd>${esc(quantity)}</dd></div>`;
 if(kind==='raidDrop'&&record.type)facts+=`<div><dt>巢穴属性</dt><dd>${esc(record.type==='ANY'?'不限':types[record.type]?.[0]||record.type)}</dd></div>`;
 const hasConditions=c=>c&&Object.entries(c).some(([k,v])=>k!=='additionalProperties'&&v!==null&&(!Array.isArray(v)||v.length>0));
 let conditions='';
 if(hasConditions(record.condition))conditions+=`<p><b>环境条件：</b><br>${rich(environmentText(record.condition))}</p>`;
 if(hasConditions(record.anticondition))conditions+=`<p><b>排除条件：</b><br>${rich(environmentText(record.anticondition))}</p>`;
 if(record.rarityMultipliers?.length)conditions+=record.rarityMultipliers.map(m=>`<p><b>权重倍率：</b>× ${esc(m.multiplier)}${hasConditions(m.condition)?'<br>'+rich(environmentText(m.condition)):''}</p>`).join('');
 return `<article class="acquisition-card"><div class="acquisition-heading">${icon}<div><span class="acquisition-label">${label}</span><strong>${name}</strong>${identifier?`<small class="source-identifier">${esc(identifier)}</small>`:''}</div></div>${facts?`<dl class="acquisition-facts">${facts}</dl>`:''}${conditions?`<div class="acquisition-conditions">${conditions}</div>`:''}</article>`;
}
function referenceDropHTML(drop){
 return Object.entries(drop).filter(([k,v])=>Array.isArray(v)&&v.length&&dropLabels[k]&&!(k==='pokemonHeldList'&&drop.pokemonheldDrop?.length)).map(([k,v])=>`<section class="acquisition-group"><h3>${dropLabels[k]}</h3>${v.some(r=>r?.rarity!==undefined)?'<p class="section-note acquisition-note">相对权重参与候选项的抽取计算，不是出现百分比。</p>':''}<div class="acquisition-list">${v.map(r=>acquisitionCard(k,r)).join('')}</div></section>`).join('')||'<p class="section-note">应用没有收录额外获取渠道。</p>';
}
